    "majority-element": {
      "1:plain": "def majorityElement(nums: list[int]) -> int:\n    # Boyer-Moore Voting Algorithm\n    candidate = nums[0]\n    count = 1\n    # Find candidate\n    for i in range(1, len(nums)):\n        if count == 0:    #This is true during the start or a new element having more count than the current Majority element\n            # Pick a new candidate when count drops to zero or During the first iteration\n            candidate = nums[i]    \n            count = 1\n        elif nums[i] == candidate:  #Same element\n            count += 1\n        else:                       #New Element\n            count -= 1\n\n    # The candidate is the majority element\n    return candidate"
    },
    "linked-list-cycle": {
      "1:plain": "class Solution:\n    def hasCycle(self, head: Optional[ListNode]) -> bool:\n        slow = head\n        fast = head\n        while fast and fast.next:  #While fast pointer and fast.next pointer is not NULL\n            slow = slow.next          # one move for slow pointer \n            fast = fast.next.next     # Two moves for fast pointer\n            if slow is fast:          #Cycle detected\n                return True\n        return False"
    },
    "number-of-islands": {
      "1:plain": "class Solution:\n    def numIslands(self, grid: list[list[str]]) -> int:\n        if not grid:  # Handle empty grid\n            return 0\n        # Initialize grid\n        rows, cols = len(grid), len(grid[0])  # Get grid dimensions\n        count = 0     # Track no.of Islands\n        directions = [(1,0), (-1,0), (0,1), (0,-1)]  # Define directions\n\n        for row in range(rows):  # Scan very cell using nested loops\n            for col in range(cols):\n                # The above for loop will execute only after the below discovered Island is fully explored using BFS queue.\n                if grid[row][col] == '1':  # New Island discovered\n                    count += 1   # This count is returned at the end of the function, which gives the no.of Islands\n\n                    # BFS to mark entire island\n                    queue = [(row, col)]  # Create a queue with starting cell.\n                    grid[row][col] = 'V'  # Mark as visited\n\n                    while queue:  # Process the queue\n                        curr_row, curr_col = queue.pop(0)  # Remove the first cell and store its co-ordinates\n\n                        # explore the neighbors in S, N, E, W order ( order is from \"directions\" list)\n                        for dr, dc in directions:\n                            new_row = curr_row + dr\n                            new_col = curr_col + dc\n\n                            if 0 <= new_row < rows and 0 <= new_col < cols:  # Verify that the neighbor (new_row,new_col) is within the grid.\n                                if grid[new_row][new_col] == '1':  # If neighbour is Land\n                                    grid[new_row][new_col] = 'V'  # Mark as visted\n                                    queue.append((new_row, new_col))    # Insert into queue\n\n        return count"
    },
    "valid-parentheses": {
      "0:plain": "class Solution:\n    def isValid(self, s: str) -> bool:\n        stack = []\n        close_to_open = {\n            ')': '(',\n            ']': '[',\n            '}': '{',\n        }\n        for ch in s:\n            if ch in close_to_open:   #Satisfies only for closed brackets. Not for open brackets\n                if stack and stack[-1] == close_to_open[ch]:  #If stack is not empty and top is equal to current character\n                    stack.pop()\n                else:\n                    return False\n            else:   # Append for open brackets\n                stack.append(ch)\n        return not stack"
    },
    "fruit-into-baskets": {
      "0:plain": "class Solution:\n    def totalFruit(self, fruits: List[int]) -> int:\n        count = {} # dictionary storing each fruit type and its frequency inside the current window\n        left = best = 0 # left boundary of the sliding window and maximum number of fruits collected so far.\n        for right in range(len(fruits)):  # right moves from left to right through the array, adding one tree at a time.\n            count[fruits[right]] = count.get(fruits[right], 0) + 1\n            while len(count) > 2:  # len(count) is the number of distinct fruit types in the current window.\n                count[fruits[left]] -= 1\n                if count[fruits[left]] == 0:  # If a fruit type no longer appears in the current window, remove its key from the dictionary.\n                    del count[fruits[left]]\n                left += 1\n            best = max(best, right - left + 1)\n        return best"
    },
    "invert-binary-tree": {
      "0:plain": "class Solution:\n    def invertTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:\n        if not root:  # If root is None, the node doesn't exist.\n            return None\n        left = self.invertTree(root.left) # This recursively inverts the entire left subtree and stores its returned root in left.\n        right = self.invertTree(root.right) # This recursively inverts the entire right subtree and stores its returned root in right.\n        root.left = right\n        root.right = left\n        return root"
    },
    "koko-eating-bananas": {
      "0:plain": "import math\n\nclass Solution:\n    def minEatingSpeed(self, piles: List[int], h: int) -> int: # Function takes pile List and the maximum number of hours available before guards come\n        def hours_needed(k: int) -> int:  # If Koko eats at speed k, how many total hours will she need?\n            return sum(math.ceil(p / k) for p in piles)\n        left, right = 1, max(piles)\n        while left < right:\n            mid = (left + right) // 2\n            if hours_needed(mid) <= h:\n                right = mid\n            else:\n                left = mid + 1\n        return left"
    },
