    "permutation-in-string": {
      "0:rcs": "class Solution:\n    def checkInclusion(self, s1: str, s2: str) -> bool:\n        if len(s1) > len(s2):                  # No window of the needed length fits.\n            return False\n        s1_count = [0] * 26                    # Target letter counts from s1.\n        window_count = [0] * 26                # Letter counts in the current window.\n        for i in range(len(s1)):               # Build target and the first window.\n\n        # ord() returns the Unicode code point of a character.\n        # ord('c') - ord('a') ~ 99 - 97 = 2 , converts a lowercase letter into an index between 0 and 25\n            s1_count[ord(s1[i]) - ord('a')] += 1\n            window_count[ord(s2[i]) - ord('a')] += 1\n        matches = 0                            # How many of 26 letters currently agree.\n        for c in range(26):\n            if s1_count[c] == window_count[c]:\n                matches += 1\n        left = 0\n        for right in range(len(s1), len(s2)):  # Slide the fixed-width window right.\n            if matches == 26:                  # First window already matched.\n                return True\n            enter = ord(s2[right]) - ord('a')  # Letter entering on the right.\n            if window_count[enter] == s1_count[enter]:  # Was equal -> about to break.\n                matches -= 1\n            window_count[enter] += 1\n            if window_count[enter] == s1_count[enter]:  # Now equal -> restored.\n                matches += 1\n            leave = ord(s2[left]) - ord('a')   # Letter leaving on the left.\n            if window_count[leave] == s1_count[leave]:  # Was equal -> about to break.\n                matches -= 1\n            window_count[leave] -= 1\n            if window_count[leave] == s1_count[leave]:  # Now equal -> restored.\n                matches += 1\n            left += 1\n        return matches == 26                   # Check the final window too.",
      "0:plain": "# Return True if any substring of s2 has exactly the same character frequencies as s1\nclass Solution:\n    def checkInclusion(self, s1: str, s2: str) -> bool:\n        if len(s1) > len(s2): # If s1 is longer than s2, there is no way for s2 to contain a substring with the same length as s1.\n            return False\n        # Create two frequency arrays.\n        s1_count = [0] * 26\n        window_count = [0] * 26 \n# We create two frequency arrays because we need to compare the character frequencies of s1 against the current window in s2.\n\n        for i in range(len(s1)):\n\n        # ord() returns the Unicode code point of a character.\n        # ord('c') - ord('a') ~ 99 - 97 = 2 , converts a lowercase letter into an index between 0 and 25\n            s1_count[ord(s1[i]) - ord('a')] += 1\n            window_count[ord(s2[i]) - ord('a')] += 1\n        matches = 0\n        for c in range(26):\n            if s1_count[c] == window_count[c]:\n                matches += 1\n        left = 0\n        for right in range(len(s1), len(s2)):\n            if matches == 26:\n                return True\n            enter = ord(s2[right]) - ord('a')\n            if window_count[enter] == s1_count[enter]:\n                matches -= 1\n            window_count[enter] += 1\n            if window_count[enter] == s1_count[enter]:\n                matches += 1\n            leave = ord(s2[left]) - ord('a')\n            if window_count[leave] == s1_count[leave]:\n                matches -= 1\n            window_count[leave] -= 1\n            if window_count[leave] == s1_count[leave]:\n                matches += 1\n            left += 1\n        return matches == 26"
    },
