    "merge-two-sorted-lists": {
      "0:plain": "class Solution:\n    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:\n        dummy = ListNode()  #Create empty linked list and point dummy to it\n        tail = dummy        # Point tail also to dummy.Tail moves forward as we add nodes and dummy stays at head.\n        l1, l2 = list1, list2\n        while l1 and l2:   #Compare the current values of both lists and append the smaller node to the merged list.\n            if l1.val <= l2.val:\n                tail.next = l1\n                l1 = l1.next\n            else:\n                tail.next = l2\n                l2 = l2.next\n            tail = tail.next  # After appending a node, move tail forward to the newly added node.tail always points to the last node in the merged list.\n        # Exit while loop when either l1 or l2 reaches the end (becomes None).\n        if l1:\n            tail.next = l1  # If l1 still has nodes, attach the remaining sorted l1 list\n        else:\n            tail.next = l2  # Otherwise, attach the remaining sorted l2 list\n        return dummy.next"
    },
    "top-k-frequent-elements": {
      "1:plain": "from collections import Counter # Counter tallies occurrences in one O(n) pass, giving value -> frequency.\n#nums = [1, 2, 2, 3, 3, 3]\n#count = Counter(nums)\n#count = {1: 1, 2: 2, 3: 3}  \n\nclass Solution:\n    def topKFrequent(self, nums: List[int], k: int) -> List[int]:\n        count = Counter(nums)   # HashMap\n        n = len(nums)\n        buckets = [[] for i in range(n + 1)]  # buckets[f] will hold every value that occurs exactly f times; n + 1 slots cover frequencies 0 to n.\n        for value, freq in count.items():   # Iterate over hashmap and insert those values into buckets\n            buckets[freq].append(value)  # Key of hashmap is Freq in bucket and value of hash is the value at index(Freq).\n        result = []\n        for freq in range(n, 0, -1):  # Iterate from right end of the array.\n            for value in buckets[freq]:\n                result.append(value)\n                if len(result) == k:  # When we get the top K elements\n                    return result\n        return result"
    },
    "spark:mask-pii-last-four": {
      "0:primary": "from pyspark.sql.functions import col, regexp_replace  # Import column reference + regex replacement functions.\n\nclean = regexp_replace(  # Remove all non-digit characters from phone.\n    col('phone'),        # Input column.\n    r'\\D',               # Regex: \\D = any NON-digit; r'' = raw string.\n    ''                   # Replace matches with nothing → removes them.\n)\n# Regex: r'\\D' → \\D = NOT a digit → '(987) 654-3210' → '9876543210'.\n\nmasked = regexp_replace(  # Mask every digit except the final 4.\n    clean,                 # Use cleaned phone number.\n    r'\\d(?=\\d{4})',        # Regex: \\d = one digit; (?=...) = lookahead; \\d{4} = 4 following digits.\n    '*'                    # Replace matched digits with '*'.\n)\n# Regex: \\d(?=\\d{4}) → \"digit followed by 4 digits\" → '9876543210' → '******3210'.\n# Why lookahead? It checks the next 4 digits without consuming them, so the final 4 remain unchanged.\n\nresult = users.withColumn(  # Add the masked value as a new column.\n    'phone_masked',         # New column name.\n    masked                  # Masking expression.\n)\n\nresult.select(              # Keep only required columns.\n    'user_id', 'phone', 'phone_masked'\n).show(truncate=False)      # show() is an ACTION → Spark executes the transformations and displays the result."
    },
    "container-with-most-water": {
      "1:plain": "class Solution:\n    def maxArea(self, height: List[int]) -> int:\n        left, right = 0, len(height) - 1\n        best = 0\n        while left < right:\n            area = (right - left) * min(height[left], height[right])  # Area formula\n            best = max(best, area)   # Update the best\n            if height[left] < height[right]:   # Move the pointers\n                left += 1\n            else:\n                right -= 1\n        return best"
    },
