    "maximum-depth-of-binary-tree": {
      "0:plain": "class Solution:\n    def maxDepth(self, root: Optional[TreeNode]) -> int:  #depth of a tree is 1 + the depth of its deeper subtree\n        if not root:\n            return 0\n        left = self.maxDepth(root.left)\n        right = self.maxDepth(root.right)\n        return 1 + max(left, right)"
    },
    "product-of-array-except-self": {
      "1:plain": "class Solution:\n    def productExceptSelf(self, nums: List[int]) -> List[int]:\n        n = len(nums)\n        answer = [1] * n  # Create an Answer array\n        prefix = 1\n        for i in range(n):  # Iterate from begining of array\n            answer[i] = prefix  #just assign\n            prefix *= nums[i]   #Same for prefix and suffix\n        suffix = 1\n        for i in range(n - 1, -1, -1):  # Iterate from end of an array\n            answer[i] *= suffix  #Multiply and assign\n            suffix *= nums[i]\n        return answer"
    },
