    "remove-nth-node-from-end-of-list": {
      "0:plain": "class Solution:\n    def removeNthFromEnd(self, head: Optional[ListNode], n: int) -> Optional[ListNode]:\n        dummy = ListNode(0, head)  # Create a dummy node\n        fast = dummy\n        slow = dummy\n        for i in range(n):   # If N nodes to be removed, move the fast pointer by N nodes.\n            fast = fast.next\n        while fast.next:     # Move slow and fast one node at a time. When fast reaches the end, slow is at the node before the one to remove.\n            fast = fast.next\n            slow = slow.next\n        slow.next = slow.next.next  # Skip the node to be removed by making the previous node (slow) point directly to the node after the target node.\n        return dummy.next"
    },
    "spark:filter-rows-matching-regex": {
      "0:primary": "from pyspark.sql.functions import col  # Import col() to reference the email column.\n\nPAT = r'^[\\w.+-]+@[\\w-]+\\.[\\w.-]+$'  # Regex defining the expected email pattern.\n\n# Regex: r'^[\\w.+-]+@[\\w-]+\\.[\\w.-]+$'\n# ^          → Start of string.\n# [\\w.+-]+   → One or more allowed username characters: letters/digits/_, '.', '+', '-'.\n# @          → Literal '@'.\n# [\\w-]+     → One or more letters/digits/_, or '-'; represents the domain name.\n# \\.         → Literal '.'; backslash escapes '.' because plain '.' means \"any character\".\n# [\\w.-]+    → One or more letters/digits/_, '.', or '-'; represents the domain extension.\n# $          → End of string.\n#\n# Overall → The ENTIRE email must match this pattern.\n\n\nvalid = users.filter(             # Keep only rows where the email matches the regex.\n    col('email').rlike(PAT)       # rlike() returns True when the email matches PAT.\n)\n\ninvalid = users.filter(           # Create the rejected/invalid DataFrame.\n    ~col('email').rlike(PAT)      # ~ negates True → False and False → True, keeping non-matching rows.\n)\n\nvalid.show(truncate=False)        # Display valid emails without truncating values.\ninvalid.show(truncate=False)      # Display invalid emails without truncating values."
    },
    "spark:orders-on-consecutive-days": {
      "0:secondary": "from pyspark.sql.window import Window\nfrom pyspark.sql.functions import col, lag, datediff\n\ndays = orders.select('customer_id', 'order_date').distinct()  # Get the distinct orders\n\nw = (Window   #  PySpark window specification builder\n     .partitionBy('customer_id')\n     .orderBy('order_date'))\n\nprev_day = lag('order_date').over(w)  # prev_day is a PySpark Column expression, not an actual column in your DataFrame yet.\n\nresult = (days\n    .withColumn('gap', datediff(col('order_date'), prev_day))  # Gap between curr and prev order\n    .filter(col('gap') == 1)      # Gap==1 means orders are on consecutive days\n    .select('customer_id').distinct())\nresult.show()"
    },
