  // Every problem registry the unified app exposes an .all() on.
  function registries() {
    return [B, window.PYDSA, window.PYSPARK, window.SQLLAB,
            window.NUMPY, window.PANDAS, window.LEARN];
  }

  function applyToProblem(p) {
    if (!p || !p.id) return;
    var id = p.id;
    if (OV.desc[id] != null && typeof p.description === "string") {
      p.description = OV.desc[id];
    }
    var lg = OV.logic[id];
    if (lg && p.approaches) {
      for (var k in lg) if (lg.hasOwnProperty(k)) {
        var ai = parseInt(k, 10);
        if (p.approaches[ai]) p.approaches[ai].logic = lg[k];
      }
    }
    var cd = OV.code[id];
    if (cd && p.approaches) {
      for (var kk in cd) if (cd.hasOwnProperty(kk)) {
        var parts = kk.split(":");
        var ci = parseInt(parts[0], 10);
        var mode = parts[1];
        if (p.approaches[ci] && (mode === "rcs" || mode === "plain")) {
          p.approaches[ci][mode] = cd[kk];
        }
      }
    }
  }

  function applyAll() {
    var regs = registries(), i, j;
    for (i = 0; i < regs.length; i++) {
      var r = regs[i];
      if (!r || typeof r.all !== "function") continue;
      var list;
      try { list = r.all(); } catch (e) { continue; }
      if (!list || !list.length) continue;
      for (j = 0; j < list.length; j++) applyToProblem(list[j]);
    }
  }
  B.applyOverridesAll = applyAll;

